{
  "name": "Julabo FP50 恒温循环冷却器",
  "name_en": "Julabo FP50 Recirculating Chiller",
  "manufacturer": "Julabo",
  "description": "Julabo FP50 是一款实验室用恒温循环冷却器，可通过循环液体为外部设备或实验过程提供稳定的冷却与温度控制。它适用于需要维持恒定工作温度的仪器、样品或装置。",
  "description_en": "The Julabo FP50 is a laboratory recirculating chiller that provides stable cooling and temperature control to external equipment or experimental processes through circulating fluid. It is used where instruments, samples, or setups need a controlled operating temperature.",
  "actions": [
    {
      "action_name": "auto-init",
      "description": "初始化恒温循环冷却器通信。",
      "description_en": "Initialize communication with the recirculating chiller."
    },
    {
      "action_name": "auto-read",
      "description": "读取设备返回数据。",
      "description_en": "Read returned data from the device."
    },
    {
      "action_name": "auto-write",
      "description": "向设备写入命令。",
      "description_en": "Write a command to the device."
    },
    {
      "action_name": "auto-get_version",
      "description": "读取设备标识或版本信息。",
      "description_en": "Read the device identification or version information."
    },
    {
      "action_name": "auto-start_chiller",
      "description": "启动冷却循环器运行。",
      "description_en": "Start chiller operation."
    },
    {
      "action_name": "auto-stop_chiller",
      "description": "停止冷却循环器运行。",
      "description_en": "Stop chiller operation."
    },
    {
      "action_name": "auto-get_status",
      "description": "获取设备状态。",
      "description_en": "Get device status."
    },
    {
      "action_name": "auto-get_set_temp",
      "description": "获取设定温度。",
      "description_en": "Get the set temperature."
    },
    {
      "action_name": "auto-set_temp",
      "description": "设置目标温度。",
      "description_en": "Set the target temperature."
    },
    {
      "action_name": "auto-get_temp",
      "description": "获取当前温度。",
      "description_en": "Get the current temperature."
    },
    {
      "action_name": "auto-set_power",
      "description": "设置加热或制冷功率。",
      "description_en": "Set the heating or cooling power."
    }
  ],
  "tag_hints": [
    "recirculating chiller",
    "laboratory temperature control",
    "cooling circulator",
    "heating and cooling",
    "circulating fluid temperature stabilization",
    "serial-controlled chiller"
  ]
}

